        /**
        Bitmask of (optional) autopilot capabilities (64 bit). If a bit is set, the autopilot supports this
        capability.
        */
        [Flags]
        enum MAV_PROTOCOL_CAPABILITY {
            /**
            Autopilot supports the MISSION_ITEM float message type.
            Note that MISSION_ITEM is deprecated, and autopilots should use MISSION_ITEM_INT instead.
            */
            MAV_PROTOCOL_CAPABILITY_MISSION_FLOAT = 1,
            /**
            Autopilot supports the new param float message type.
            ⚠ DEPRECATED since 2022-03, replaced by MAV_PROTOCOL_CAPABILITY_PARAM_ENCODE_C_CAST
            */
            MAV_PROTOCOL_CAPABILITY_PARAM_FLOAT = 2,
            /**
            Autopilot supports MISSION_ITEM_INT scaled integer message type.
            Note that this flag must always be set if missions are supported, because missions must always use
            MISSION_ITEM_INT (rather than MISSION_ITEM, which is deprecated).
            */
            MAV_PROTOCOL_CAPABILITY_MISSION_INT = 4,
            /**
            Autopilot supports COMMAND_INT scaled integer message type.
            */
            MAV_PROTOCOL_CAPABILITY_COMMAND_INT = 8,
            /**
            Parameter protocol uses byte-wise encoding of parameter values into param_value (float) fields:
            https://mavlink.io/en/services/parameter.html#parameter-encoding.
            Note that either this flag or MAV_PROTOCOL_CAPABILITY_PARAM_ENCODE_C_CAST should be set if the parameter
            protocol is supported.
            */
            MAV_PROTOCOL_CAPABILITY_PARAM_ENCODE_BYTEWISE = 16,
            /**
            Autopilot supports the File Transfer Protocol v1: https://mavlink.io/en/services/ftp.html.
            */
            MAV_PROTOCOL_CAPABILITY_FTP = 32,
            /**
            Autopilot supports the SET_ATTITUDE_TARGET message (for commanding attitude from an offboard controller).
            */
            MAV_PROTOCOL_CAPABILITY_SET_ATTITUDE_TARGET = 64,
            /**
            Autopilot supports the SET_POSITION_TARGET_LOCAL_NED message (for commanding position and velocity targets in
            local NED frame).
            */
            MAV_PROTOCOL_CAPABILITY_SET_POSITION_TARGET_LOCAL_NED = 128,
            /**
            Autopilot supports the SET_POSITION_TARGET_GLOBAL_INT message (for commanding position and velocity targets in
            global scaled integers).
            */
            MAV_PROTOCOL_CAPABILITY_SET_POSITION_TARGET_GLOBAL_INT = 256,
            /**
            Autopilot supports terrain protocol / data handling.
            */
            MAV_PROTOCOL_CAPABILITY_TERRAIN = 512,
            /**
            Reserved for future use.
            */
            MAV_PROTOCOL_CAPABILITY_RESERVED3 = 1024,
            /**
            Autopilot supports the MAV_CMD_DO_FLIGHTTERMINATION command (flight termination).
            */
            MAV_PROTOCOL_CAPABILITY_FLIGHT_TERMINATION = 2048,
            /**
            Autopilot supports onboard compass calibration.
            */
            MAV_PROTOCOL_CAPABILITY_COMPASS_CALIBRATION = 4096,
            /**
            Autopilot supports MAVLink version 2.
            */
            MAV_PROTOCOL_CAPABILITY_MAVLINK2 = 8192,
            /**
            Autopilot supports mission fence protocol.
            */
            MAV_PROTOCOL_CAPABILITY_MISSION_FENCE = 16384,
            /**
            Autopilot supports mission rally point protocol.
            */
            MAV_PROTOCOL_CAPABILITY_MISSION_RALLY = 32768,
            /**
            Reserved for future use.
            */
            MAV_PROTOCOL_CAPABILITY_RESERVED2 = 65536,
            /**
            Parameter protocol uses C-cast of parameter values to set the param_value (float) fields:
            https://mavlink.io/en/services/parameter.html#parameter-encoding.
            Note that either this flag or MAV_PROTOCOL_CAPABILITY_PARAM_ENCODE_BYTEWISE should be set if the parameter
            protocol is supported.
            */
            MAV_PROTOCOL_CAPABILITY_PARAM_ENCODE_C_CAST = 131072,
            /**
            This component implements/is a gimbal manager. This means the GIMBAL_MANAGER_INFORMATION, and other messages
            can be requested.
            */
            MAV_PROTOCOL_CAPABILITY_COMPONENT_IMPLEMENTS_GIMBAL_MANAGER = 262144,
            /**
            Component supports locking control to a particular GCS independent of its system (via
            MAV_CMD_REQUEST_OPERATOR_CONTROL).
            🚧 WIP
            */
            MAV_PROTOCOL_CAPABILITY_COMPONENT_ACCEPTS_GCS_CONTROL = 524288,
            /**
            Autopilot has a connected gripper. MAVLink Grippers would set MAV_TYPE_GRIPPER instead.
            🚧 WIP
            */
            MAV_PROTOCOL_CAPABILITY_GRIPPER = 1048576,
        }

