            /**
            alpha release
            */
            FIRMWARE_VERSION_TYPE_ALPHA = 64,
            /**
            beta release
            */
            FIRMWARE_VERSION_TYPE_BETA = 128,
            /**
            release candidate
            */
            FIRMWARE_VERSION_TYPE_RC = 192,
            /**
            official stable release
            */
            FIRMWARE_VERSION_TYPE_OFFICIAL = 255,
        }

        // ═════════════════════════ SI units (mirrored from mavschema.xsd) ═════════════════════════

        /** Non-transmittable constants container with every unit string MAVLink allows; [Units] attributes reference it. */
        public struct SI_Unit {
            public struct time {
                public const string s            = "s"; // seconds
                public const string ds           = "ds"; // deciseconds
                public const string cs           = "cs"; // centiseconds
                public const string ms           = "ms"; // milliseconds
                public const string us           = "us"; // microseconds
                public const string ns           = "ns"; // nanoseconds
                public const string Hz           = "Hz"; // Herz
                public const string MHz          = "MHz"; // Mega-Herz
            }

            public struct distance {
                public const string km           = "km"; // kilometres
                public const string dam          = "dam"; // decametres
                public const string m            = "m"; // metres
                public const string m_2          = "m^2"; // metres squared (typically used in variance)
                public const string m_s          = "m/s"; // metres per second
                public const string m_s_s        = "m/s/s"; // metres per second per second
                public const string m_s_5        = "m/s*5"; // metres per second * 5 required from dagar for HIGH_LATENCY2 message
                public const string dm           = "dm"; // decimetres
                public const string dm_s         = "dm/s"; // decimetres per second
                public const string cm           = "cm"; // centimetres
                public const string cm_2         = "cm^2"; // centimetres squared (typically used in variance)
                public const string cm_s         = "cm/s"; // centimetres per second
                public const string mm           = "mm"; // millimetres
                public const string mm_s         = "mm/s"; // millimetres per second
                public const string mm_h         = "mm/h"; // millimetres per hour
            }

            public struct temperature {
                public const string K            = "K"; // Kelvin
                public const string degC         = "degC"; // degrees Celsius
                public const string cdegC        = "cdegC"; // centi degrees Celsius
            }

            public struct angle {
                public const string rad          = "rad"; // radians
                public const string rad_s        = "rad/s"; // radians per second
                public const string mrad_s       = "mrad/s"; // milli-radians per second
