        // ═════════════════════════ demo topology ═════════════════════════

        // MAVLink defines no network topology (packets only carry system_id / component_id), so the demo
        // invents two hosts and lets either side send any message without changing state.

        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct GroundControl : Host { }

        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct MicroAirVehicle : Host { }

        interface CommunicationChannel : Connects<GroundControl, MicroAirVehicle> {
            // Every message class of the dialect, in both directions; the FSM never transitions.
            // The recursive @scope would also collect the metadata attribute classes declared at the end of
            // this interface, so they are filtered out by name.
            // Replace with explicit l____________ / ____________r branches to route messages per host.
            [_____lr_____<@standard>(SkipName: @"Attribute$")]
            struct Start { }
        }

        // ═════════════════════════ MAVLink metadata attributes ═════════════════════════

        // AdHoc custom attributes: the generator carries each one into the generated code as constants
        // attached to the field, so units, invalid markers, display hints etc. stay available at runtime.
        // They must live inside the project interface (the agent expects every class in a project); the
        // connection's branch excludes them from its pack scope with SkipName.

        /** SI unit of a numeric field (a SI_Unit constant). */
        public class UnitsAttribute : Attribute { public UnitsAttribute(string units) { } }

        /** Value (or, for arrays, the [value] / [value:] / [v1,,v3,] notation) that marks the field as not set. */
        public class InvalidAttribute : Attribute { public InvalidAttribute(string value) { } }

        /** The field identifies the sensor / battery instance the message is about. */
        public class InstanceAttribute : Attribute { }

        /** UI hint, e.g. "bitmask": show the enum values as check boxes. */
        public class DisplayAttribute : Attribute { public DisplayAttribute(string hint) { } }

        /** printf-style display format. */
        public class PrintFormatAttribute : Attribute { public PrintFormatAttribute(string format) { } }

        /** Default value of the field. */
        public class DefaultAttribute : Attribute { public DefaultAttribute(string value) { } }

        /** Scale factor: actual value = stated value * multiplier. */
        public class MultiplierAttribute : Attribute { public MultiplierAttribute(string factor) { } }

        /** Minimum value hint for UIs (not a wire constraint: [Invalid] markers may lie outside it). */
        public class MinValueAttribute : Attribute { public MinValueAttribute(double value) { } public MinValueAttribute(string value) { } }

        /** Maximum value hint for UIs (not a wire constraint: [Invalid] markers may lie outside it). */
        public class MaxValueAttribute : Attribute { public MaxValueAttribute(double value) { } public MaxValueAttribute(string value) { } }

        /** Declared after the &lt;extensions/&gt; marker: present in MAVLink 2 frames only. */
        public class ExtensionFieldAttribute : Attribute { }
    }
}
